const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const poi = ee.Geometry.Point(-22.413665983340525, 63.8577134531586);
  // Grindavik coordinates (approximate center)
  const grindavik = ee.Geometry.Point(-22.433, 63.844);
  const date = '2024-01-16';

  // 2. Data Acquisition & Check
  // MODIS Land Surface Temperature and Emissivity (MOD11A1.061)
  // LST_Day_1km is surface temperature, QC_Day is quality control.
  let collection = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(poi.union(grindavik));

  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS LST data found for January 16, 2024.");
    console.log("C1");
    return;
  }
  console.log(`Images found for ${date}: ${collectionSize}`);

  const image = collection.first();

  // Define a cloud/quality mask function
  // Bits 0-1: LST quality (00 = good, 01 = good, 10 = questionable, 11 = bad)
  // Bits 6-7: Cloud contamination (00 = clear, 01 = cloudy, 10 = mixed, 11 = not set)
  const applyQualityMask = (img) => {
    const qc = img.select('QC_Day');
    const lstQuality = qc.bitwiseAnd(3); // Extract bits 0-1
    const cloudFlag = qc.rightShift(6).bitwiseAnd(3); // Extract bits 6-7

    // Mask out pixels with bad LST quality or cloudy conditions
    const goodQuality = lstQuality.lte(1); // 00 or 01
    const clearSky = cloudFlag.eq(0); // 00

    return img.updateMask(goodQuality.and(clearSky));
  };

  const maskedImage = applyQualityMask(image).select('LST_Day_1km');

  // Convert LST from Kelvin*0.02 to Celsius
  const toCelsius = (img) => img.multiply(0.02).subtract(273.15);
  const lstCelsius = toCelsius(maskedImage);

  // 3. Processing (Calculate pixel count to detect C2)
  const scale = 1000; // MODIS LST resolution is 1km

  // Get pixel count for POI
  const poiCountDict = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: poi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const poiValidPixels = poiCountDict['LST_Day_1km'];

  // Get pixel count for Grindavik
  const grindavikCountDict = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: grindavik,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const grindavikValidPixels = grindavikCountDict['LST_Day_1km'];

  if (poiValidPixels === 0 || grindavikValidPixels === 0) {
    console.log(`POI valid pixels: ${poiValidPixels}, Grindavik valid pixels: ${grindavikValidPixels}`);
    console.log("No valid pixels after cloud/quality masking for one or both locations.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const poiLSTDict = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: poi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const poiLST = poiLSTDict['LST_Day_1km'];

  const grindavikLSTDict = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: grindavik,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const grindavikLST = grindavikLSTDict['LST_Day_1km'];

  // 5. Validation & Final Answer
  if (poiLST === null || isNaN(poiLST) || grindavikLST === null || isNaN(grindavikLST)) {
    console.log(`POI LST: ${poiLST}, Grindavik LST: ${grindavikLST}`);
    console.log("C3"); // Calculation failed
    return;
  }

  console.log(`POI LST (C): ${poiLST.toFixed(2)}, Valid Pixels: ${poiValidPixels}`);
  console.log(`Grindavik LST (C): ${grindavikLST.toFixed(2)}, Valid Pixels: ${grindavikValidPixels}`);

  if (poiLST > grindavikLST) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
